
.footer {
  border-top: 1px solid var(--border);
  background: var(--bg);
}

.footer-inner {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 40px;
  padding-block: 56px 44px;
}

.footer-logo {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.footer-logo img {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  object-fit: cover;
  border: 1px solid var(--border-gold);
}

.footer-logo-sub {
  display: block;
  font-family: var(--font-body);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.3em;
  color: var(--gold);
}

.footer-tagline {
  margin-top: 16px;
  font-family: var(--font-display);
  font-style: italic;
  font-size: 15.5px;
  color: var(--text-muted);
}

.footer-col-title {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 14px;
}

.footer-text {
  font-size: 14px;
  line-height: 1.7;
  color: var(--text-muted);
  max-width: 260px;
}

.footer-link {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 14px;
  color: var(--text-muted);
  margin-top: 10px;
  transition: color 0.2s ease;
}

.footer-link:hover {
  color: var(--gold-soft);
}

.footer-instagram {
  margin-top: 0;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding-block: 22px;
  border-top: 1px solid var(--border);
  font-size: 12.5px;
  color: var(--text-muted);
}

@media (max-width: 820px) {
  .footer-inner {
    grid-template-columns: 1fr;
    gap: 30px;
  }
}
